/// A protected request was rejected because its session is no longer valid.
class SessionExpiredException implements Exception {
  const SessionExpiredException();

  static const message = 'Сеанс eNet ID завершён. Войдите снова.';

  @override
  String toString() => message;
}

class AuthUser {
  const AuthUser({
    required this.id,
    required this.email,
    required this.name,
  });

  /// Stable UUID generated by the eNet API for this account.
  final String id;
  final String email;
  final String name;
}

class EcosystemService {
  const EcosystemService({
    required this.id,
    required this.name,
    required this.description,
    required this.url,
  });

  final String id;
  final String name;
  final String description;
  final String url;
}

class WorkspaceTask {
  const WorkspaceTask({
    required this.id,
    required this.title,
    required this.description,
    required this.completed,
    required this.createdAt,
    required this.updatedAt,
    required this.dueAt,
  });

  final String id;
  final String title;
  final String description;
  final bool completed;
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime? dueAt;
}

class AccountSession {
  const AccountSession({
    required this.id,
    required this.device,
    required this.createdAt,
    required this.lastSeenAt,
    required this.expiresAt,
    required this.current,
  });

  final String id;
  final String device;
  final DateTime createdAt;
  final DateTime lastSeenAt;
  final DateTime expiresAt;
  final bool current;
}

class AccountNotification {
  const AccountNotification({
    required this.id,
    required this.type,
    required this.title,
    required this.body,
    required this.createdAt,
    required this.readAt,
  });

  final String id;
  final String type;
  final String title;
  final String body;
  final DateTime createdAt;
  final DateTime? readAt;

  bool get unread => readAt == null;
}

class NotificationFeed {
  const NotificationFeed({required this.notifications, required this.unreadCount});

  final List<AccountNotification> notifications;
  final int unreadCount;
}

/// Abstract authentication and account services. Demo implementation is only for tests.
abstract class AuthRepository {
  Future<AuthUser> signIn({required String email, required String password});
  Future<AuthUser> signUp({required String name, required String email, required String password});
  Future<void> requestPasswordReset(String email);
  Future<void> signOut();
  Future<AuthUser?> restoreSession();
  Future<bool> checkServer();
  Future<List<EcosystemService>> listServices();
  Future<void> changePassword(String currentPassword, String nextPassword);
  Future<int> revokeOtherSessions();
  Future<AuthUser> updateName(String name);
  Future<List<AccountSession>> listSessions();
  Future<void> revokeSession(String sessionId);
  Future<String> getApiEndpoint();
  Future<void> setApiEndpoint(String value);
  Future<List<String>> favoriteServices();
  Future<List<String>> saveFavoriteServices(List<String> serviceIds);
  Future<NotificationFeed> listNotifications();
  Future<void> readNotification(String id);
  Future<int> readAllNotifications();
  Future<List<WorkspaceTask>> listTasks();
  Future<WorkspaceTask> createTask({
    required String title,
    required String description,
    DateTime? dueAt,
  });
  Future<WorkspaceTask> updateTask({
    required String id,
    required String title,
    required String description,
    DateTime? dueAt,
  });
  Future<WorkspaceTask> setTaskCompleted(String id, bool completed);
  Future<void> deleteTask(String id);
}
